# One icon family is shared across logo handoff and UI.
for alias, source in {'x':'close','chevron':'chevron-down','briefcase':'work','pin':'location','alert':'warning','file':'resume'}.items():
 path=ROOT/'04_Icones'/'SVG'/f'{source}.svg'
 if path.exists(): ICONS[alias]=re.sub(r'<title>.*?</title>', '', path.read_text().split('>',1)[1].rsplit('</svg>',1)[0])
for name in list(ICONS):
 path=ROOT/'04_Icones'/'SVG'/f'{name}.svg'
 if path.exists(): ICONS[name]=re.sub(r'<title>.*?</title>', '', path.read_text().split('>',1)[1].rsplit('</svg>',1)[0])
def icon(name,cls=''):
 return f'<svg class="icon {cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{ICONS[name]}</svg>'
def button(text,kind='primary',extra='',ic=None):
 return f'<button type="button" class="button {kind}" {extra}>{icon(ic) if ic else ""}{text}</button>'
def badge(text,kind='neutral'):
 return f'<span class="badge {kind}"><span class="status-dot"></span>{text}</span>'

