js='''/* Offline demonstration only. No network requests, storage, tracking, or real submissions. */
(() => {
  const toast = document.getElementById('toast');
  function notify(text) { if (!toast) return; document.getElementById('toast-text').textContent=text; toast.hidden=false; }
  document.getElementById('toast-close')?.addEventListener('click',()=>{toast.hidden=true;});
  document.querySelectorAll('[data-demo]').forEach(b=>b.addEventListener('click',()=>notify(b.dataset.demo)));
  document.querySelectorAll('button[role="switch"]').forEach(b=>b.addEventListener('click',()=>{b.setAttribute('aria-checked',String(b.getAttribute('aria-checked')!=='true'));}));
  document.querySelectorAll('.chip').forEach(b=>b.addEventListener('click',()=>{b.setAttribute('aria-pressed',String(b.getAttribute('aria-pressed')!=='true'));}));
  document.querySelectorAll('[data-save]').forEach(b=>b.addEventListener('click',()=>{const saved=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(saved));notify(saved?'Vaga salva.':'Vaga removida dos salvos.');}));
  document.querySelectorAll('[role="tablist"]').forEach(list=>{
    const tabs=[...list.querySelectorAll('[role="tab"]')];
    function activate(tab,focus=false){tabs.forEach(t=>{const on=t===tab;t.setAttribute('aria-selected',String(on));t.tabIndex=on?0:-1;document.getElementById(t.getAttribute('aria-controls')).hidden=!on;});if(focus)tab.focus();}
    tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>activate(tab));tab.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(index+1)%tabs.length;if(e.key==='ArrowLeft')next=(index-1+tabs.length)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();activate(tabs[next],true);}});});
  });
  const pageButtons=[...document.querySelectorAll('[data-page]')];let page=1;
  function setPage(n){page=Math.max(1,Math.min(5,n));pageButtons.forEach(b=>{if(Number(b.dataset.page)===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});document.querySelector('[data-page-prev]').disabled=page===1;document.querySelector('[data-page-next]').disabled=page===5;document.getElementById('page-status').textContent=`Página ${page} de 5`;}
  pageButtons.forEach(b=>b.addEventListener('click',()=>setPage(Number(b.dataset.page))));
  document.querySelector('[data-page-prev]')?.addEventListener('click',()=>setPage(page-1));
  document.querySelector('[data-page-next]')?.addEventListener('click',()=>setPage(page+1));
  const form=document.getElementById('demo-form');
  form?.addEventListener('submit',e=>{e.preventDefault();const input=document.getElementById('demo-name'),control=document.getElementById('demo-name-control'),help=document.getElementById('demo-name-help');if(!input.value.trim()){input.setAttribute('aria-invalid','true');control.classList.add('error');help.className='error-text';help.textContent='Digite um nome fictício para continuar.';input.focus();return;}input.removeAttribute('aria-invalid');control.classList.remove('error');help.className='help';help.textContent='Use um nome fictício para testar.';notify('Formulário validado neste exemplo. Nenhum dado foi enviado.');});
  document.getElementById('pause-search')?.addEventListener('click',e=>{const b=e.currentTarget,paused=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(paused));b.querySelector('span').textContent=paused?'Retomar candidaturas':'Pausar candidaturas';document.getElementById('search-status').textContent=paused?'Candidaturas pausadas.':'Suas preferências';notify(paused?'Candidaturas pausadas.':'Candidaturas retomadas.');});
  document.getElementById('mobile-menu-toggle')?.addEventListener('click',e=>{const b=e.currentTarget,open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));document.getElementById('mobile-menu-panel').hidden=!open;b.setAttribute('aria-label',open?'Fechar navegação':'Abrir navegação');});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(toast)toast.hidden=true;const menu=document.getElementById('mobile-menu-panel'),toggle=document.getElementById('mobile-menu-toggle');if(menu&&!menu.hidden){menu.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Abrir navegação');toggle.focus();}}});
})();
'''
(C/'components.js').write_text(js)
(C/'LEIA-ME.md').write_text('''# Componentes Apliquefy

Abra `catalogo.html` diretamente no navegador. Não exige servidor, conta, compilação ou internet. `aplicacao.html` demonstra os mesmos componentes em desktop e celular. Preserve a estrutura de pastas para carregar os tokens, a fonte e as assinaturas.

## Conteúdo

- Botões: principal, secundário, discreto e destrutivo; hover, foco, pressionado, desabilitado e carregando.
- Campos de texto, busca, seleção; mensagens de ajuda, erro, foco e estado bloqueado.
- Checkbox, radio, switch, chips de seleção e formulário com validação demonstrativa.
- Cartões de vaga, favoritos, acompanhamento de candidaturas e etapas.
- Status, alertas, toast, estado vazio e skeleton de carregamento.
- Abas, paginação, avatar, tooltip, disclosure e navegação responsiva.
- Exports SVG editáveis e PNG em 1x / 2x; composições vetoriais da aplicação em desktop e celular.

## Interações implementadas

Favoritar vagas, mudar preferências, alternar switches, validar formulário, navegar entre abas usando teclado, mudar página ilustrativa, abrir menu móvel, pausar/retomar o estado do exemplo e fechar mensagens. Todos os dados são fictícios. Nada é enviado ou persistido. A interface não está conectada a serviços externos.

## Integração

`components.css` importa `../06_Tokens/tokens.css`; classes são independentes de frameworks. A família CSS `Apliquefy Display` carrega a Regular R2 (400) e a Bold original (700), ambas locais. A fonte Display é restrita a títulos e marca; os textos funcionais usam a pilha `Inter, system-ui, -apple-system, Segoe UI, sans-serif`, com fallback local. Inter não é redistribuída neste pacote.

As prévias `composicao-desktop` e `composicao-mobile` são composições vetoriais da identidade aplicada, não capturas de navegador. O catálogo HTML é uma implementação separada dos mesmos componentes.

Os SVG de componentes mantêm texto editável em fonte de sistema, sem imagens incorporadas. São modelos de construção, não componentes de software executáveis. Os PNG têm o mesmo enquadramento dos SVG.

## Acessibilidade e limites

Controles usam rótulos associados, foco visível, nome acessível e mensagens que não dependem só de cor. Abas implementam setas, Home e End. Movimento é reduzido conforme a preferência do sistema. Área padrão dos controles: 44 px. O arquivo demonstra boas práticas e deve passar pela revisão de acessibilidade do produto integrado, com leitores de tela e conteúdo real.

Roxo de ação: #7A3BFF, hover #6527DC, pressionado/foco #5420BF. Sucesso usa #08773A sobre #EAF8EF; atenção #A64500 sobre #FFF2E6; erro #B42318 sobre #FFF0EE. Laranja e verde vivos são acentos, não fundos de texto branco.
''')
(T/'LEIA-ME.md').write_text('''# Tokens Apliquefy

`tokens.css` é o contrato CSS usado pelos componentes. `design-tokens.json` contém cores, medidas, tipografia, semântica e notas de uso em uma estrutura JSON de tokens legível, sem declaração de conformidade a schema externo. A seção `metadata` e as descrições de uso são documentação; adapte a estrutura ao pipeline da equipe.

## Hierarquia

- Base: grafite #14121C, branco #FFFFFF, superfície #F6F4FA.
- Ação: roxo #7A3BFF; hover #6527DC; pressionado #5420BF.
- Acentos: laranja #FF7A00 e verde #22D36A.
- Semântica: tons escuros próprios para sucesso, atenção, erro e informação; sempre com texto/ícone.
- Espaços: 4, 8, 12, 16, 24, 32, 48, 64 e 96 px.
- Raios: 6 px em etiquetas, 10 px em controles, 16 px em cartões.
- Controles: 44 px padrão; 36 px apenas variante compacta.
- Corpo: 14/16 px, entrelinha 1.5; títulos Display 28/36/48 px, entrelinha 1.12.

O gradiente documentado é uma referência de cor. Use a geometria e os stops do SVG oficial do símbolo ao reproduzir a assinatura, pois o arquivo mestre tem precedência sobre interpretações em CSS.
''')
